const tickets = [["T1","The app crashes every time I upload a PNG larger than 5MB."],["T2","Please add a dark mode to the dashboard."],["T3","How do I export my invoices as CSV?"],["T4","Checkout returns HTTP 500 when the cart has more than 20 items."],["T5","It would be great to have SSO with Okta."],["T6","Where can I change my notification email?"]];
const specialist = {bug:"bug-fixer", feature:"feature-analyst", question:"support-agent"};
const cls = await Promise.all(tickets.map(async ([id,text]) => {
  const r = await task({description:"Classify this support ticket as exactly one of: bug, feature, question.\nTicket: "+text, subagentType:"general-purpose", label:"classify "+id, responseSchema:{type:"object",properties:{category:{type:"string",enum:["bug","feature","question"]}},required:["category"]}});
  return {id,text,category:r.category};
}));
const out = await Promise.all(cls.map(async t => {
  const r = await task({description:"Handle this support ticket ("+t.id+", classified as "+t.category+"): "+t.text+"\nReturn a single-line outcome (likely cause/next step, effort/impact, or answer).", subagentType:specialist[t.category], label:t.id+" "+t.category, responseSchema:{type:"object",properties:{outcome:{type:"string"}},required:["outcome"]}});
  return t.id+" ["+t.category+" -> "+specialist[t.category]+"]: "+r.outcome;
}));
out.join("\n")
